<script setup lang="ts">
import { SearchableSelect } from '#components'
const { t } = useLanguage()
import { Printer } from 'lucide-vue-next'
const route=useRoute(),db=useSupabase()
const month=ref(String(route.query.month||nowMonth())),classId=ref(String(route.query.class||'')),teacherId=ref(String(route.query.teacher||''))
const classes=ref<any[]>([]),teachers=ref<any[]>([]),rows=ref<any[]>([]),settlements=ref<any[]>([]),loading=ref(false),error=ref(''),loaded=ref(false)
const reportMonth=ref(''),reportClass=ref(''),reportTeacher=ref('')
const sum=(list:any[],key:string)=>list.reduce((a,r)=>a+Number(r[key]||0),0)
const groups=computed(()=>{const map=new Map<string,any>();for(const r of rows.value){const key=r.class_id+':'+r.teacher_id;if(!map.has(key))map.set(key,{key,class_id:r.class_id,teacher_id:r.teacher_id,class_name:r.class_name,teacher_name:r.teacher_name,rows:[]});map.get(key).rows.push(r)}return [...map.values()].map(g=>({...g,history:settlements.value.filter(s=>s.class_id===g.class_id&&s.teacher_id===g.teacher_id)}))})
const paid=(history:any[])=>sum(history.filter(r=>!r.voided_at),'amount')
const changed=computed(()=>month.value!==reportMonth.value||classId.value!==reportClass.value||teacherId.value!==reportTeacher.value)
async function load(){if(!db)return;loaded.value=false;loading.value=true;error.value='';rows.value=[];settlements.value=[];try{if(!isValidMonth(month.value))throw Error(t('financialUi.finance.monthInvalid'));const m=month.value,c=classId.value,teacher=teacherId.value;const q=await db.rpc('class_month_report',{p_month:monthStart(m),p_class:c||null,p_teacher:teacher||null});if(q.error)throw q.error;rows.value=q.data.rows;settlements.value=q.data.settlements;reportMonth.value=m;reportClass.value=c;reportTeacher.value=teacher;loaded.value=true}catch(e){error.value=errText(e)}finally{loading.value=false}}
function print(){if(loaded.value&&!changed.value)window.print()}
onMounted(async()=>{if(!db)return;try{[classes.value,teachers.value]=await Promise.all([allRows(()=>db.from('class_rooms').select('id,title,start_time,end_time').order('id')),allRows(()=>db.from('teachers').select('id,full_name').order('id'))]);await load()}catch(e){error.value=errText(e)}})
</script>
<template><div><div class="no-print"><PageTitle :title="t('financialUi.monthlyReport.title')" :subtitle="t('financialUi.monthlyReport.subtitle')"><button class="btn primary" :disabled="!loaded||changed||!rows.length||loading" @click="print"><Printer :size="17"/> {{ t('financialUi.monthlyReport.printPdf') }}</button></PageTitle><Notice :message="error" kind="error"/><form class="table-toolbar" @submit.prevent="load"><label>{{ t('financialUi.month') }}<input v-model="month" type="month" required/></label><label>{{ t('financialUi.class') }}<SearchableSelect v-model="classId" :options="classes" label-key="title" :placeholder="t('financialUi.monthlyReport.allClasses')" /></label><label>{{ t('financialUi.teacher') }}<SearchableSelect v-model="teacherId" :options="teachers" label-key="full_name" :placeholder="t('financialUi.monthlyReport.allTeachers')" /></label><button class="btn" :disabled="loading">{{ t('financialUi.monthlyReport.showReport') }}</button></form><p v-if="loading">{{ t('financialUi.loading') }}</p><p v-if="changed">{{ t('financialUi.monthlyReport.changed') }}</p><p v-if="loaded&&!rows.length">{{ t('financialUi.monthlyReport.noHistory') }}</p></div>
<PrintReport v-if="loaded&&groups.length>1" :title="t('financialUi.monthlyReport.teacherSettlementSummary')" :subtitle="reportMonth"><table class="data-table"><thead><tr><th>{{ t('financialUi.teacher') }}</th><th>{{ t('financialUi.class') }}</th><th>{{ t('financialUi.monthlyReport.entitlement') }}</th><th>{{ t('financialUi.teacherSettlements.settled') }}</th><th>{{ t('financialUi.monthlyReport.remainingSettlement') }}</th></tr></thead><tbody><tr v-for="g in groups" :key="g.key"><td>{{g.teacher_name}}</td><td>{{g.class_name}}</td><td>{{money(sum(g.rows,'teacher_entitlement'))}}</td><td>{{money(paid(g.history))}}</td><td>{{money(sum(g.rows,'teacher_entitlement')-paid(g.history))}}</td></tr></tbody><tfoot><tr><th colspan="2">{{ t('financialUi.total') }}</th><th>{{money(sum(rows,'teacher_entitlement'))}}</th><th>{{money(paid(settlements))}}</th><th>{{money(sum(rows,'teacher_entitlement')-paid(settlements))}}</th></tr></tfoot></table></PrintReport>
<PrintReport v-for="g in groups" :key="g.key" :title="t('financialUi.monthlyReport.title')" :subtitle="t('financialUi.monthlyReport.classTeacherMonthStudents',{className:g.class_name,teacher:g.teacher_name,month:reportMonth,count:g.rows.length})">
<p v-if="classes.find(c=>c.id===g.class_id)?.start_time">{{ t('financialUi.monthlyReport.currentClassTime') }} {{timeShort(classes.find(c=>c.id===g.class_id)?.start_time)}} – {{timeShort(classes.find(c=>c.id===g.class_id)?.end_time)}}</p>
<div class="table-wrap"><table class="data-table"><thead><tr><th>{{ t('financialUi.number') }}</th><th>{{ t('financialUi.student') }}</th><th>{{ t('financialUi.monthlyReport.originalFee') }}</th><th>{{ t('financialUi.monthlyReport.applicableFee') }}</th><th>{{ t('financialUi.monthlyReport.prorationBasis') }}</th><th>{{ t('financialUi.monthlyReport.discount') }}</th><th>{{ t('financialUi.adjustments.paidAmount') }}</th><th>{{ t('financialUi.monthlyReport.received') }}</th><th>{{ t('financialUi.materials.remaining') }}</th><th>{{ t('financialUi.monthlyReport.teacherDiscountShare') }}</th><th>{{ t('financialUi.monthlyReport.teacherEntitlement') }}</th><th>{{ t('financialUi.monthlyReport.officeShare') }}</th><th>{{ t('financialUi.monthlyReport.manualAdjustment') }}</th></tr></thead><tbody><tr v-for="(r,i) in g.rows" :key="r.id"><td>{{i+1}}</td><td>{{r.student_name}}<small class="material-id">{{r.student_code}}</small></td><td>{{money(r.original_fee)}}</td><td>{{money(r.base_fee)}}</td><td>{{t(`registration.${r.proration_rule}`)}}</td><td>{{money(r.discount)}}</td><td>{{money(r.amount_due)}}</td><td>{{money(r.paid_total)}}</td><td>{{money(r.balance_due)}}</td><td>{{money(r.teacher_discount_share)}}</td><td>{{money(r.teacher_entitlement)}}</td><td>{{money(r.center_entitlement)}}</td><td>{{r.manually_adjusted?`${r.manual_adjustment_reason} · ${r.manual_adjusted_at||''}`:t('financialUi.automatic')}}</td></tr></tbody></table></div>
<section class="report-summary"><h3>{{ t('financialUi.monthlyReport.classSummary') }}</h3><div class="summary-row"><span>{{ t('financialUi.studentPlural') }}</span><strong>{{g.rows.length}}</strong></div><div v-for="[key,label] in [['original_fee',t('financialUi.monthlyReport.totalOriginalFee')],['base_fee',t('financialUi.monthlyReport.totalApplicableFee')],['discount',t('financialUi.monthlyReport.totalDiscount')],['amount_due',t('financialUi.monthlyReport.tuitionReceivable')],['paid_total',t('financialUi.monthlyReport.tuitionCollected')],['balance_due',t('financialUi.monthlyReport.studentBalances')],['teacher_entitlement',t('financialUi.monthlyReport.teacherEntitlement')],['center_entitlement',t('financialUi.monthlyReport.officeEntitlement')]]" :key="key" class="summary-row"><span>{{label}}</span><strong>{{money(sum(g.rows,key!))}}</strong></div><div class="summary-row"><span>{{ t('financialUi.monthlyReport.settledWithTeacher') }}</span><strong>{{money(paid(g.history))}}</strong></div><div class="summary-row"><span>{{ t('financialUi.monthlyReport.teacherSettlementBalance') }}</span><strong>{{money(sum(g.rows,'teacher_entitlement')-paid(g.history))}}</strong></div></section>
<h3>{{ t('financialUi.monthlyReport.settlementHistory') }}</h3><table class="data-table"><thead><tr><th>{{ t('financialUi.paymentDate') }}</th><th>{{ t('financialUi.amount') }}</th><th>{{ t('financialUi.note') }}</th><th>{{ t('financialUi.status') }}</th></tr></thead><tbody><tr v-for="s in g.history" :key="s.id"><td>{{s.paid_on}}</td><td>{{money(s.amount)}}</td><td>{{s.note||'—'}}</td><td>{{s.voided_at?t('financialUi.monthlyReport.voidedReason',{reason:s.void_reason}):t('financialUi.valid')}}</td></tr><tr v-if="!g.history.length"><td colspan="4">{{ t('financialUi.monthlyReport.noSettlement') }}</td></tr></tbody></table><p>{{ t('financialUi.monthlyReport.historyNote') }}</p>
</PrintReport></div></template>
